# The question asks for "p53-mediated cell cycle gene regulation"
# In Reactome_2022, this maps to the parent pathway:
# "TP53 Regulates Transcription Of Cell Cycle Genes" (R-HSA-6791312)
# This is the Reactome term that describes p53-mediated regulation of cell cycle genes.
target_terms = [
    "TP53 Regulates Transcription Of Cell Cycle Genes R-HSA-6791312",
    "TP53 Regulates Transcription of Cell Cycle Genes R-HSA-6791312",
]

or_val = None
for target in target_terms:
    exact_match = results_enr[results_enr['Term'] == target]
    if exact_match.shape[0] > 0:
        or_val = exact_match['Odds Ratio'].values[0]
        print(f"\nExact match for '{target}': Odds Ratio = {or_val}")
        break

if or_val is None:
    # Case-insensitive search
    for target in ["TP53 Regulates Transcription Of Cell Cycle Genes", "TP53 Regulates Transcription of Cell Cycle Genes"]:
        matches = results_enr[results_enr['Term'].str.lower() == target.lower()]
        if matches.shape[0] > 0:
            or_val = matches['Odds Ratio'].values[0]
            print(f"\nCase-insensitive match for '{target}': Odds Ratio = {or_val}")
            break

if or_val is None:
    # Fall back to the best p53+cell cycle match
    print("Falling back to best p53+cell cycle match...")
    best = None
    for i, row in results_enr.iterrows():
        tl = row['Term'].lower()
        if 'tp53' in tl and 'cell cycle' in tl:
            if best is None or row['P-value'] < best['P-value']:
                best = row
    if best is not None:
        or_val = best['Odds Ratio']
        print(f"Best p53 cell cycle term: '{best['Term']}': OR={or_val}")
    else:
        print("No p53+cell cycle term found!")

if or_val is not None:
    import os
    os.makedirs('codex_output', exist_ok=True)
    with open('codex_output/answer.txt', 'w') as f:
        f.write(f"{or_val}\n")
    print(f"Answer written to codex_output/answer.txt")
else:
    print("Could not determine odds ratio.")
